import PropTypes from "prop-types";

const Card = ({ children, reverse = false }) => (
    <div className={`card ${reverse ? 'reverse' : ''}`}>
        {children}
    </div>
);

Card.propTypes = {
    children: PropTypes.node.isRequired,
    reverse: PropTypes.bool,
};

export default Card;
